export const getBlogPosts = (language: Language = 'pt'): BlogPost[] => {
  return blogPostsData[language] || blogPostsData.pt;
};

export const getBlogPostBySlug = (slug: string, language: Language = 'pt'): BlogPost | undefined => {
  const posts = getBlogPosts(language);
  return posts.find((p) => p.slug === slug);
};
